sp_widget.client_script:
api.controller = function($window) {

    var c = this;

    /* ADD COMPANY */
    c.addCompany = function() {

        if (!c.data.isPlacementAdmin) {
            return;
        }

        $window.location.href =
            '?id=company_form&mode=new';
    };


    /* VIEW COMPANY */
    c.viewCompany = function(company, $event) {

        if ($event) {
            $event.stopPropagation();
        }

        if (!company || !company.sys_id) {
            return;
        }

        $window.location.href =
            '?id=company_form' +
            '&sys_id=' + encodeURIComponent(company.sys_id) +
            '&mode=view';
    };


    /* EDIT COMPANY */
    c.editCompany = function(company, $event) {

        if ($event) {
            $event.stopPropagation();
        }

        if (!c.data.isPlacementAdmin) {
            return;
        }

        if (!company || !company.sys_id) {
            return;
        }

        $window.location.href =
            '?id=company_form' +
            '&sys_id=' + encodeURIComponent(company.sys_id) +
            '&mode=edit';
    };

};

sp_widget.css:
/* =========================================================
   NEXORA COMPANIES / PLACEMENT DRIVES
   ========================================================= */

.nexora-companies-container {
  width:85vw;
    padding: 70px !important;
    background: #ffffff !important;
    min-height: 100% !important;
    box-sizing: border-box !important;
}



/* =========================================================
   PAGE HEADER
   ========================================================= */

.nexora-page-header {
    position: relative !important;
    display: flex !important;
    justify-content: space-between !important;
    align-items: center !important;

    background: #193b56 !important;
    color: #ffffff !important;

    border-radius: 22px !important;

    padding: 34px 40px !important;

    margin-bottom: 22px !important;

    overflow: hidden !important;

    box-shadow:
        0 12px 30px rgba(25, 59, 86, 0.12) !important;
}



/* Decorative circles */

.nexora-page-header:before,
.nexora-page-header:after {
    content: "" !important;

    position: absolute !important;

    border:
        1px solid rgba(255, 255, 255, 0.08) !important;

    border-radius: 50% !important;

    pointer-events: none !important;
}


.nexora-page-header:before {
    width: 250px !important;
    height: 250px !important;

    right: -80px !important;
    top: -110px !important;
}


.nexora-page-header:after {
    width: 190px !important;
    height: 190px !important;

    right: -35px !important;
    top: -75px !important;
}



/* =========================================================
   HEADER LEFT
   ========================================================= */

.nexora-header-left {
    position: relative !important;

    z-index: 5 !important;

    flex: 1 !important;

    min-width: 0 !important;
}


.nexora-eyebrow {
    color: #ff6b5b !important;

    font-size: 15px !important;

    font-weight: 800 !important;

    letter-spacing: 1.4px !important;

    margin-bottom: 10px !important;
}


.nexora-page-header h2 {
    margin: 0 !important;

    font-size: 32px !important;

    line-height: 1.15 !important;

    font-weight: 800 !important;

    color: #ffffff !important;
}


.nexora-page-header p {
    margin: 12px 0 0 !important;

    color: #a9c4d9 !important;

    font-size: 15px !important;

    line-height: 1.5 !important;
}



/* =========================================================
   HEADER RIGHT
   ========================================================= */

.nexora-header-actions {
    position: relative !important;

    z-index: 10 !important;

    display: flex !important;

    align-items: center !important;

    justify-content: flex-end !important;

    gap: 12px !important;

    margin-left: 20px !important;
}



/* =========================================================
   HEADER ICON
   ========================================================= */

.nexora-header-icon {
    position: relative !important;

    z-index: 5 !important;

    width: 64px !important;

    height: 64px !important;

    min-width: 64px !important;

    border-radius: 16px !important;

    background: #ff6b5b !important;

    display: flex !important;

    align-items: center !important;

    justify-content: center !important;

    color: #ffffff !important;

    font-size: 26px !important;

    box-shadow:
        0 10px 20px rgba(255, 107, 91, 0.22) !important;
}



/* =========================================================
   BUTTON BASE
   ========================================================= */

.company-btn {
    display: inline-flex !important;

    align-items: center !important;

    justify-content: center !important;

    gap: 8px !important;

    min-height: 44px !important;

    padding: 10px 18px !important;

    border: none !important;

    border-radius: 9px !important;

    font-size: 14px !important;

    font-weight: 700 !important;

    line-height: 1 !important;

    cursor: pointer !important;

    text-align: center !important;

    white-space: nowrap !important;

    transition:
        background 0.2s ease,
        transform 0.2s ease,
        box-shadow 0.2s ease !important;
}



/* =========================================================
   PRIMARY BUTTON
   ========================================================= */

.company-btn-primary {
    background: #ff6b5b !important;

    color: #ffffff !important;

    box-shadow:
        0 6px 14px rgba(255, 107, 91, 0.20) !important;
}


.company-btn-primary:hover {
    background: #f45d4d !important;

    color: #ffffff !important;

    transform: translateY(-1px) !important;

    box-shadow:
        0 8px 18px rgba(255, 107, 91, 0.25) !important;
}


.company-btn-primary:active {
    transform: translateY(0) !important;
}



/* =========================================================
   SEARCH BAR
   ========================================================= */

.nexora-search-wrapper {
    margin-bottom: 22px !important;
}


.nexora-search {
    position: relative !important;

    width: 100% !important;

    background: #ffffff !important;

    border:
        1px solid #e2e9ef !important;

    border-radius: 12px !important;

    box-shadow:
        0 3px 12px rgba(25, 59, 86, 0.05) !important;
}


.nexora-search i {
    position: absolute !important;

    left: 16px !important;

    top: 50% !important;

    transform: translateY(-50%) !important;

    color: #8aa1b2 !important;

    font-size: 14px !important;

    z-index: 2 !important;
}


.nexora-search input {
    width: 100% !important;

    height: auto !important;

    min-height: 46px !important;

    border: none !important;

    outline: none !important;

    background: transparent !important;

    box-shadow: none !important;

    padding:
        13px 16px 13px 42px !important;

    font-size: 14px !important;

    color: #193b56 !important;
}


.nexora-search input::placeholder {
    color: #9aaab5 !important;
}



/* =========================================================
   COMPANY GRID
   ========================================================= */

.nexora-company-grid {
    display: grid !important;

    grid-template-columns:
        repeat(2, minmax(0, 1fr)) !important;

    gap: 22px !important;

    width: 100% !important;
}



/* =========================================================
   COMPANY CARD
   ========================================================= */

.company-card-wrapper {
    min-width: 0 !important;
}


.company-card {
    background: #ffffff !important;

    border:
        1px solid #e1e8ee !important;

    border-radius: 16px !important;

    padding: 22px !important;

    display: flex !important;

    flex-direction: column !important;

    justify-content: space-between !important;

    min-height: 100% !important;

    box-shadow:
        0 6px 18px rgba(25, 59, 86, 0.055) !important;

    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease !important;
}


.company-card:hover {
    transform: translateY(-3px) !important;

    box-shadow:
        0 12px 28px rgba(25, 59, 86, 0.10) !important;
}



/* =========================================================
   COMPANY HEADER
   ========================================================= */

.company-header {
    padding-bottom: 14px !important;

    margin-bottom: 15px !important;

    border-bottom:
        1px solid #edf1f4 !important;
}


.company-title-row {
    display: flex !important;

    justify-content: space-between !important;

    align-items: flex-start !important;

    gap: 12px !important;
}


.company-name {
    font-size: 20px !important;

    font-weight: 800 !important;

    color: #193b56 !important;

    margin: 0 !important;

    line-height: 1.3 !important;

    word-break: break-word !important;
}


.company-location {
    background: #52b9d9 !important;

    color: #ffffff !important;

    border-radius: 5px !important;

    padding: 4px 9px !important;

    font-size: 12px !important;

    font-weight: 700 !important;

    white-space: nowrap !important;
}



/* =========================================================
   COMPANY DETAILS
   ========================================================= */

.company-details {
    flex: 1 !important;
}


.company-details p {
    margin: 0 0 8px !important;

    font-size: 14px !important;

    color: #59636c !important;

    line-height: 1.5 !important;
}


.company-details p strong {
    color: #193b56 !important;

    font-weight: 700 !important;
}



/* =========================================================
   ACTION BUTTONS
   ========================================================= */

.company-actions {
    margin-top: 18px !important;

    display: flex !important;

    gap: 10px !important;

    align-items: center !important;
}


.nexora-btn {
    flex: 1 !important;

    display: inline-flex !important;

    align-items: center !important;

    justify-content: center !important;

    gap: 7px !important;

    border: none !important;

    border-radius: 8px !important;

    padding: 10px 14px !important;

    min-height: 42px !important;

    font-size: 14px !important;

    font-weight: 700 !important;

    cursor: pointer !important;

    text-align: center !important;

    transition:
        background 0.2s ease,
        transform 0.2s ease !important;
}


.nexora-btn-secondary {
    background: #edf3f8 !important;

    color: #193b56 !important;
}


.nexora-btn-secondary:hover {
    background: #e1ebf2 !important;

    color: #193b56 !important;

    transform: translateY(-1px) !important;
}



/* =========================================================
   EMPTY STATE
   ========================================================= */

.nexora-empty-state {
    background: #ffffff !important;

    border:
        1px solid #e2e9ef !important;

    border-radius: 16px !important;

    text-align: center !important;

    padding: 50px 20px !important;

    box-shadow:
        0 6px 18px rgba(25, 59, 86, 0.04) !important;
}


.nexora-empty-state > i {
    display: block !important;

    color: #8aa1b2 !important;

    font-size: 38px !important;

    margin-bottom: 15px !important;
}


.nexora-empty-state h4 {
    margin: 0 0 8px !important;

    color: #193b56 !important;

    font-size: 20px !important;

    font-weight: 800 !important;
}


.nexora-empty-state p {
    margin: 0 0 20px !important;

    color: #7c8993 !important;

    font-size: 14px !important;
}


.empty-add-button {
    margin-top: 5px !important;
}



/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 900px) {

    .nexora-page-header {
        padding: 28px !important;
    }

    .nexora-header-actions {
        margin-left: 12px !important;
    }

    .nexora-page-header h2 {
        font-size: 27px !important;
    }

}


@media (max-width: 767px) {

    .nexora-companies-container {
        padding: 12px 12px 30px !important;
    }


    .nexora-page-header {
        flex-direction: column !important;

        align-items: stretch !important;

        gap: 20px !important;

        padding: 25px 22px !important;
    }


    .nexora-header-actions {
        width: 100% !important;

        margin-left: 0 !important;

        justify-content: space-between !important;
    }


    .nexora-header-icon {
        width: 54px !important;

        height: 54px !important;

        min-width: 54px !important;

        font-size: 22px !important;
    }


    .company-btn-primary {
        flex: 1 !important;
    }


    .nexora-page-header h2 {
        font-size: 25px !important;
    }


    .nexora-page-header p {
        font-size: 14px !important;
    }


    .nexora-company-grid {
        grid-template-columns: 1fr !important;
    }


    .company-title-row {
        flex-direction: column !important;

        gap: 8px !important;
    }


    .company-location {
        align-self: flex-start !important;
    }


    .company-actions {
        flex-direction: column !important;
    }


    .nexora-btn {
        width: 100% !important;
    }

}


@media (max-width: 480px) {

    .nexora-header-actions {
        flex-direction: column-reverse !important;

        align-items: stretch !important;
    }


    .nexora-header-icon {
        align-self: flex-end !important;
    }


    .company-btn-primary {
        width: 100% !important;
    }

}

sp_widget.script:
(function() {

    /* =====================================================
       NEXORA PLACEMENT MANAGEMENT
       SERVER SCRIPT
       ===================================================== */

    data.companies = [];

    var userID = gs.getUserID();


    /* =====================================================
       ROLE DETECTION
       ===================================================== */

    /*
     * IMPORTANT:
     *
     * We use ONE variable called userType.
     *
     * admin   = Placement Admin / TPO
     * officer = Placement Officer
     * student = Student
     *
     * The order is intentional:
     *
     * placement_admin
     *       ↓
     *      EDIT
     *
     * placement_officer
     *       ↓
     *      VIEW
     *
     * student
     *       ↓
     *     APPLY
     */

    data.userType = 'student';


    /* =====================================================
       PLACEMENT ADMIN / TPO
       ===================================================== */

    if (
        gs.hasRole('x_snc_college_pl_0.placement_admin')
    ) {

        data.userType = 'admin';

    }


    /* =====================================================
       PLACEMENT OFFICER
       ===================================================== */

    else if (
        gs.hasRole('x_snc_college_pl_0.placement_officer')
    ) {

        data.userType = 'officer';

    }


    /* =====================================================
       STUDENT
       ===================================================== */

    else {

        data.userType = 'student';

    }


    /* =====================================================
       ROLE FLAGS
       ===================================================== */

    /*
     * These are the ONLY flags the HTML should use.
     */

    data.isPlacementAdmin =
        (data.userType === 'admin');

    data.isPlacementOfficer =
        (data.userType === 'officer');

    data.isStudent =
        (data.userType === 'student');


    /* =====================================================
       GET COMPANY RECORDS
       ===================================================== */

    var companyGr = new GlideRecord(
        'x_snc_college_pl_0_company'
    );

    companyGr.query();


    while (companyGr.next()) {

        var companySysId =
            companyGr.getUniqueValue();


        data.companies.push({

            /* SYSTEM ID */
            sys_id:
                companySysId,


            /* COMPANY NAME */
            name:
                companyGr.getValue('company_name')
                || 'Unnamed Company',


            /* DESCRIPTION */
            description:
                companyGr.getValue('description')
                || '',


            /* HR USER */
            hrUser:
                companyGr.getDisplayValue('hr_user')
                || '',


            /* BRANCHES */
            branches:
                companyGr.getDisplayValue('allow_branches')
                || 'All Branches',


            /* MIN CGPA */
            minCgpa:
                companyGr.getValue('eligibility_cgpa')
                || 'N/A',


            /* JOB ROLE */
            role:
                companyGr.getValue('job_role')
                || '',


            /* MAX BACKLOGS */
            maxBacklogs:
                companyGr.getValue('maximum_backlogs') !== null
                ? companyGr.getValue('maximum_backlogs')
                : '',


            /* LOCATION */
            location:
                companyGr.getValue('location')
                || '',


            /* PACKAGE */
            package:
                companyGr.getValue('package')
                || 'N/A',


            /* SKILLS */
            skills:
                companyGr.getDisplayValue('skills')
                || ''

        });

    }


    /* =====================================================
       DEBUG
       ===================================================== */

    gs.info(
        'NEXORA ROLE CHECK | User: ' +
        gs.getUserName() +
        ' | userType: ' +
        data.userType +
        ' | Admin: ' +
        data.isPlacementAdmin +
        ' | Officer: ' +
        data.isPlacementOfficer +
        ' | Student: ' +
        data.isStudent
    );

})();
